def reverse_list_elements(elements, punctuation):
    """単語と対応する句読点のセットを保ったまま、順序を反転する。"""
    if len(elements) != len(punctuation):
        raise ValueError("elements と punctuation の要素数が一致している必要があります。")

    reversed_pairs = list(zip(elements, punctuation))[::-1]

    if not reversed_pairs:
        return [], []

    new_elements, new_punctuation = zip(*reversed_pairs)
    return list(new_elements), list(new_punctuation)
